		var _moduleLoaded = function(e){
			_modulesLoaded.push(e);
			_.each(_modules, function(module){
				if (smart[module].require &&  !_.difference(smart[module].require, _modulesLoaded).length){
					if (!_.contains(_modulesInit, module) && smart[module].init){
						if(_.contains(_modulesEnables, module)){
							_modulesInit.push(module);
							_.defer(function(){
								smart[module].init();
							});
						}
					}
				}
			});
		};
		var _init = function(){
			_btnLayers = $("html").find("[data-require-module]");
			_modules = _.without(_.keys(smart),"core");
			_.each(_modules, function(module){
				smart[module].require = _.filter(smart[module].require, function(module){
					return _.contains(_modules, module);
				});
			});
			_.each(_btnLayers, function(v){
				var $v = $(v);
				var module = $v.attr("data-require-module");
				var layer = $v.attr("smartLayer");
				if (_.contains(_layers,layer)){
					$v.removeClass("hide-layer");
					if (!_.contains(_modules,module)){
						$v.remove();
					}else{
						$v.removeClass("smart-no-has-module");
						//S.log(module);
						smart.eventBus.on("moduleLoaded", function(e){
							if (e === module){
									$v.removeClass("smart-disabled");
									$v.addClass("smart-enabled");
								$v.on("click", function(){
									smart.eventBus.trigger("smart:view:" + module + ":toggle");
								});
							}
						});
					}
				}
			});
			smart.eventBus.on("moduleLoaded",_moduleLoaded);
			smart.eventBus.trigger("smart:init", _modules);
		};
		var _populateLoadingErrorDescription = function (data) {
			$(".error-page-container").removeClass('hidden');
			$(".smart-loader.loader.smart-loader").attr('hidden', 'true');
			Object.keys(data).forEach(function (key) {
				$(".error-page--content").append("<p>" + key + ": " + data[key] + "</p>");
			});
			$(".error-page--content").append("<p>Timestamp: " + new Date().getTime() + "</p>");
			$(".error-page--content").append("<hr>");
		};

		var _showScaResponseError = function () {
			$(".error-scaResponse-container").removeClass('hidden');
			$(".smart-loader.loader.smart-loader").attr('hidden', 'true');
		};

		var _getParameterByName = function(name) {
			return decodeURIComponent((new RegExp('[?|&]' + name + '=' + '([^&;]+?)(&|#|;|$)').exec(window.location.search) || [, ""])[1].replace(/\+/g, '%20')) || null;
		};
		$(function(){
			if(window.scaResponse){
				window.layers = JSON.parse(window.scaResponse).features;
				_layers = _.flatten(_.union(["core","ACTIVITYDISCUSSION"],_.values(window.layers)));
				_modulesEnables = _.flatten(_.map(_layers, function(v){
					if(_layersMatch[v]){
						return _.values(_layersMatch[v]);
					}
				}));

				_init();
			}else{
				xmlHttp.onreadystatechange = function(e) {
					if (xmlHttp.readyState === 4 && xmlHttp.status === 200){
						window.scaResponse = xmlHttp.responseText;
						window.layers = JSON.parse(window.scaResponse).features;
						_layers = _.flatten(_.union(["core","ACTIVITYDISCUSSION","PANEL_CATALOG"],_.values(window.layers)));
						_modulesEnables = _.flatten(_.map(_layers, function(v){
							if(_layersMatch[v]){
								return _.values(_layersMatch[v]);
							}
						}));
						_init();
					} else if (xmlHttp.status === 401){
						_showScaResponseError();
					} else if (xmlHttp.status >= 400){
						_populateLoadingErrorDescription({Url: xmlHttp.responseURL, Status: xmlHttp.status, Response: xmlHttp.statusText});
					}
				};
				xmlHttp.addEventListener("error", function(error) {
					_populateLoadingErrorDescription({Error: "Error obtaining ScaResponse."});
				});
				xmlHttp.open("GET", _getParameterByName('smartBookUrl'), true);
				xmlHttp.withCredentials = true;
				var session = _getParameterByName('SESSION');
				if (session) {
					xmlHttp.setRequestHeader('X-Auth-Token', session);
				}

				xmlHttp.send(null);
			}
		});
		return {
			callWhenModuleLoad: function(funcToCall, moduleName){
				if (_.contains(_modulesLoaded, moduleName)){
					funcToCall(moduleName);
				}else{
					smart.eventBus.on("moduleLoaded",function(e){
						if (e === moduleName){
							funcToCall(moduleName);
						}
					});
				}
			},
			modulesLoaded: function(){
				var modulesNoLoaded = _.difference(_modulesInit, _modulesLoaded);
				if(_.size(modulesNoLoaded) > 1){
					console.error("error --> ", modulesNoLoaded);
				}else{
					modulesNoLoaded[0] === "student" || modulesNoLoaded[0] === "teacher" ? console.log("ok all modules loaded") : console.error("error --> ", modulesNoLoaded);
				}
			}
		};
