(function (smart) {
  "use strict";
  smart.activityFeedback = (function () {
    var feedbacks;
    var avatarUri;
    var _disconnect = false;
    var _tpl = _.template($("#activityFeedbackTpl").text());
    var _currentUser;
    var _init = function () {
      if (developEnv) {
        $$('head').append('<link rel="stylesheet" type="text/css" href="' + smart.scaResponse.get("cdn") + '/src/views/activityFeedbackView001/activityFeedbackView001.css">');
      }
      smart.http.get(smart.scaResponse.get("teachersService")).then(function (res) {
        var data = res.data;
       avatarUri = data[0].picture;
      }).catch(function () {
        avatarUri =  smart.scaResponse.get("cdn") + "/img/avatar-g.png";
      });
      _currentUser = "feedbacks_"+smart.scaResponse.get("scaResponseId");
      if(!_disconnect){
        smart.http.get(smart.scaResponse.get("activityTrackingService")).then(function (res) {
          feedbacks = res.data;
          smart.localStorage.setItem(_currentUser, JSON.stringify(res.data));
        }).catch(function(){
          _.delay(function(){
            if(!smart.stomp.isConnected()){
              feedbacks = JSON.parse(smart.localStorage.getItem(_currentUser));
            }
          },500);
        });
      }else{
        feedbacks = JSON.parse(smart.localStorage.getItem(_currentUser));
      }

      smart.eventBus
        .on("offlineMode", _offlineMode)
        .on("http:connected", _onlineMode)
        .trigger("moduleLoaded", "activityFeedback")
      ;
    };
    var _offlineMode = function () {
      _disconnect = true;
      if(smart.electronIntegration.isElectron()){
        $$("[feedbackAvatar]").addClass("smart-disabled");
      }
		};
    var _onlineMode = function () {
      _disconnect = false;
      if(smart.electronIntegration.isElectron()){
        $$("[feedbackAvatar]").removeClass("smart-disabled");
      }
    };
    var _getEvaluate = function(score){
      var evaluate;
      switch (score) {
        case 0:
            evaluate = "verypoor_active.svg";
        break;
        case 25:
            evaluate = "poor_active.svg";
        break;
        case 50:
            evaluate = "acceptable_active.svg";
        break;
        case 75:
            evaluate = "good_active.svg";
        break;
        case 100:
            evaluate = "excellent_active.svg";
        break;
      }
      return smart.skinService.getSkinUri() + "/emojis/"+evaluate;
    };
    var _getFeedback = function (id) {
      var feedback;
      var data = _.filter(feedbacks, function (e) {
        return e.activityId.split("/").pop() === id;
      });
      _.each(data, function (elem) {
        if (elem.result && elem.result.extensions && elem.result.completion) {
          var feedbackStatus = elem.result.success ? "pass" : "fail";
          var feedbackText = elem.result.extensions["https://w3id.org/xapi/smart/extension/result/evaluation-feedback"];
          var feedbackScore = elem.result.score.raw;
          feedback = _tpl({
            feedbackStatus: feedbackStatus,
            feedbackText: feedbackText,
            feedbackAvatar: avatarUri,
            feedbackEvaluate: _getEvaluate(feedbackScore),
          });
        }
      });
      feedback = feedback || '<div class="activityFeedback" excludePatchContent=""></div>';
      return feedback;
    };
    var _updateDataId = function (id) {
      smart.http.get(smart.scaResponse.get("activityTrackingService")).then(function (res) {
        feedbacks = res.data;
        smart.localStorage.setItem(_currentUser, JSON.stringify(res.data));
        var feedback;
        var data = _.filter(feedbacks, function (e) {
          return e.activityId.split("/").pop() === id;
        });
        _.each(data, function (elem) {
          if (elem.result && elem.result.extensions) {
            var feedbackStatus = elem.result.success ? "pass" : "fail";
            var feedbackText = elem.result.extensions["https://w3id.org/xapi/smart/extension/result/evaluation-feedback"];
            var feedbackScore = elem.result.score.raw;
            feedback = _tpl({
              feedbackStatus: feedbackStatus,
              feedbackText: feedbackText,
              feedbackAvatar: avatarUri,
              feedbackEvaluate: _getEvaluate(feedbackScore),
            });
          }
        });
        feedback = feedback || '<div class="activityFeedback" excludePatchContent=""></div>';
        return feedback;
      });
    };
    return {
      require: ["eventBus", "http", "scaResponse", "skinService", "integration"],
      init: function () {
        _init();
      },
      getDataById: function (id) {
        return _getFeedback(id);
      },
      updateDataId: function (id) {
        return _updateDataId(id);
      },
      setFeedbacks: function (data) {
        feedbacks = data;
      },
      getEvaluate:function(score){
        return _getEvaluate(score);
      }
    };
  })();
})(window.smart = window.smart || {});
(function(smart){
	"use strict";
	smart.activityFeedbackIntegration = (function(){
		var _tpl = "";
		var _tplNotAssessable = "";
		var _students;
		var _data;
		var _init = function () {
			_tpl = "<%= window.parent.smart.activityFeedback.getDataById(id) %>";
            _tplNotAssessable = $("#studentNotAssessableTpl").text();
			_update();
			app.eventBus.on("pageContent:inserted", function(){
                _update();
            });
			smart.eventBus.trigger("moduleLoaded", "activityFeedbackIntegration");
		};
		var _update = function(){
			_.each(getActivityComp(),function(v){
				_updateTemplate(v);
			});
		};
		var _updateTemplate = function(compName){
			_.each(app.edat.getViews(compName), function(view){
				var phtml = smart.utils.getVal(contentWindow,"ntxTemplateJsonViews."+compName+".views."+view+".phtml");
				var length;
				var current = 0;
				phtml = phtml.replace(/(<([^>]+)>)/ig,function(v,p1,p2){
					return v.indexOf("<%") === 0 ? "Â¬Â¬Â¬" + p2 + "â‚¬â‚¬â‚¬" : v;
				});
				length = phtml.match(/(<([^>]+)>)/ig).length;
				phtml = phtml.replace(/(<([^>]+)>)/ig,function(v){
					current++;
					return current !== length ? v : _tplNotAssessable + _tpl + v;
				});
				phtml = phtml.split("Â¬Â¬Â¬").join("<");
				phtml = phtml.split("â‚¬â‚¬â‚¬").join(">");
				app.templateCache.update(compName, view, phtml);
			});			
		};
		var getActivityComp = function(){
			var arrComps = ["qEssayActivity","activityNoInteractive","smartActivityDiscussion","qDrawActivity", "qLikertActivity", "qFormulaEssayActivity", "qSpeakingActivity", "smartActivityUploadFile"];
			return _.filter(app.edat.getComps(), function(v){
				return _.contains(arrComps, app.edat.getComp(v).name);
			});
		};
		return{
			require:["integration","eventBus","scaResponse","http","utils","student"],
			init:function(){
				_init();
			},
			getData: function(){
				return _data;
			},
			getStudents: function(){
				return _students;
			},
			getCompById: function(id){
				return app.dat.getCompById(id);
			},
			closest: function (id,elem) {
				return app.dat.closest(id,elem);
			},
			getModel: function(id){
				return app.compController.getModelById(id);
			}
		};
	})();
})(window.smart = window.smart || {});

