(function(smart){
	"use strict";
	smart.classroomControl = (function(){
		var _lockEnabled = false;
		var _pointEnabled = false;
		var _blockadeStudentsEnabled = false;
		var _enabledPictogramsControl = false;
		var _pictogramsDisplay = 'image';
		var _sendLockOn = function(){
			smart.stomp.send("student", "classroomControl:lock:on",{
				"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
				"unitUri": smart.scaResponse.get("unitUri")
			});
			smart.stomp.send("teacher", "classroomControl:lock:on",{
				"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
				"unitUri": smart.scaResponse.get("unitUri")
			});
		};
		var _sendBlockStudentsOn = function (){
			smart.stomp.send("student","classroomControl:blockStudents:on",{
				"id": smart.classroomControlIntegration.getCurrentPopup() || smart.classroomControlIntegration.getCurrentPage(),
				"unitUri": smart.scaResponse.get("unitUri")
			});
			smart.stomp.send("teacher","classroomControl:blockStudents:on",{
				"id": smart.classroomControlIntegration.getCurrentPopup() || smart.classroomControlIntegration.getCurrentPage(),
				"unitUri": smart.scaResponse.get("unitUri")
			});
		};
		var _sendPictogramsDisplay = function (e){
			_pictogramsDisplay = e.mode;
			smart.stomp.send("student","classroomControl:pictogramDisplay",{
				"mode": e.mode,
				"unitUri": smart.scaResponse.get("unitUri")	
			});
		};
		var _gotoGuided = function(e){
			smart.stomp.send("student","classroomControl:goto",e);
		};
		var _onListenerJoin = function(){
			if(_lockEnabled){
				_lockEnabled = true;
				_.delay(function(){
					_sendLockOn();	
				},1000);
			}
			if(_blockadeStudentsEnabled){
				_blockadeStudentsEnabled = true;
				_.delay(function(){
					_sendBlockStudentsOn();	
				},1000);
			}
			if(_enabledPictogramsControl){
				_.delay(function(){
					smart.stomp.send("student", "classroomControl:pictogramsControl:on",{
						"mode": _pictogramsDisplay,
						"unitUri": smart.scaResponse.get("unitUri")
					});
				},1000);
			}
		};
		var _closePopup = function(e){
			e.unitUri = smart.scaResponse.get("unitUri");
			smart.stomp.send("student","classroomControl:closePopup",e);
		};
		/* var _sendMediaEvent = function(e){
			e.unitUri= smart.scaResponse.get("unitUri");
			smart.stomp.send("student","classroomControl:sendMediaEvent",e);
		}; */
		var _currentElementChange = function(e){
			smart.stomp.send("student","classroomControl:currentElementChange",e);
		};
		var _onGotoPoint = function(){
			_pointEnabled = false;
		};
		var _onBeforeUnload = function(){
			if(_lockEnabled){
				smart.stomp.send("student", "classroomControl:lock:off",{
					"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
				smart.stomp.send("teacher", "classroomControl:lock:off",{
					"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
			}
			if(_blockadeStudentsEnabled){
				smart.stomp.send("student", "classroomControl:blockStudents:off",{
					"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
				smart.stomp.send("teacher", "classroomControl:blockStudents:off",{
					"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
			}
			if(_enabledPictogramsControl){
				smart.stomp.send("student", "classroomControl:pictogramsControl:off",{
					"mode": 'image',
					"unitUri": smart.scaResponse.get("unitUri")
				});
			}
		};
		var _init = function(){
			$(window).on("beforeunload", _onBeforeUnload);
			smart.eventBus
				.on("classroomControl:goto", _gotoGuided)
				.on("classroomControl:closePopup", _closePopup)
				.on("stomp:onTeacherNotification:classroomControlListen:isEnabled", _onListenerJoin)
				/* .on("classroomControl:sendMediaEvent", _sendMediaEvent) */
				.on("classroomControl:currentElementChange", _currentElementChange)
				.on("classroomControl:onGotoPoint", _onGotoPoint)
				.on("classroomControl:changePictogramsDisplay",_sendPictogramsDisplay)
				.on("stomp:reconnecting",_disableClassroomControl)
				.on("stomp:disconnected",_disableClassroomControl)
			;
			smart.eventBus.trigger("moduleLoaded","classroomControl");
		};
		var _disableClassroomControl = function(){
			if(_lockEnabled || _blockadeStudentsEnabled){
				smart.eventBus.trigger("smart:view:classroomControl:toggle");
			}
		};
		return {
			require: ["eventBus","stomp","teacher","scaResponse"],
			init:function(){
				_init();
			},
			isEnableLock:function(){
				return _lockEnabled;
			},
			enableLock:function(){
				smart.classroomControl.disableBlockStudents();
				if (!_lockEnabled){
					_lockEnabled = true;
					_sendLockOn();
				}
			},
			disableLock:function(){
				if (_lockEnabled){
					_lockEnabled = false;
					smart.stomp.send("student", "classroomControl:lock:off",{
						"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
						"unitUri": smart.scaResponse.get("unitUri")
					});
					smart.stomp.send("teacher", "classroomControl:lock:off",{
						"id": smart.classroomControlIntegration.getCurrentPopup()  || smart.classroomControlIntegration.getCurrentPage(),
						"unitUri": smart.scaResponse.get("unitUri")
					});
				}
			},
			toggleLock: function(){
				(smart.classroomControl.isEnableLock() ? smart.classroomControl.disableLock : smart.classroomControl.enableLock)();
			},
			gotoPoint: function(){
				_pointEnabled = true;
				smart.classroomControlIntegration.gotoPoint();
			},
			disableGotoPoint:function(){
				if (_pointEnabled){
					_pointEnabled = false;
					smart.classroomControlIntegration.disableGotoPoint();
					$$("body").css("cursor","default");
				}
			},

			//block students
			isEnableBlockStudents:function(){
				return _blockadeStudentsEnabled;
			},
			enableBlockStudents:function(){
				smart.classroomControl.disableLock();
				if (!_blockadeStudentsEnabled){
					_blockadeStudentsEnabled = true;
					_sendBlockStudentsOn();
				}
			},
			disableBlockStudents:function(){
				if (_blockadeStudentsEnabled){
					_blockadeStudentsEnabled = false;
					smart.stomp.send("student","classroomControl:blockStudents:off",{
						"id": smart.classroomControlIntegration.getCurrentPopup() || smart.classroomControlIntegration.getCurrentPage(),
						"unitUri": smart.scaResponse.get("unitUri")
					});
					smart.stomp.send("teacher","classroomControl:blockStudents:off",{
						"id": smart.classroomControlIntegration.getCurrentPopup() || smart.classroomControlIntegration.getCurrentPage(),
						"unitUri": smart.scaResponse.get("unitUri")
					});
				}
			},
			toggleBlockStudents: function(){
				(smart.classroomControl.isEnableBlockStudents() ? smart.classroomControl.disableBlockStudents : smart.classroomControl.enableBlockStudents)();
			},

			//pictograms control
			isEnabledPictogramsControl:function(){
				return _enabledPictogramsControl;
			},
			enablePictogramsControl:function(){
				var displayMode = app.compController.getInstanceById(app.dat.getCompsIdsByName('interface')[0])._modePictogramDisplay;
				_pictogramsDisplay = displayMode;
				smart.stomp.send("student","classroomControl:pictogramsControl:on",{
					"mode": _pictogramsDisplay,
					"unitUri": smart.scaResponse.get("unitUri")	
				});
			},
			disablePictogramsControl:function(){
				smart.stomp.send("student","classroomControl:pictogramsControl:off",{
					"mode": 'image',
					"unitUri": smart.scaResponse.get("unitUri")	
				});
			},
			togglePictogramsControl: function(value){
				_enabledPictogramsControl = value;
				if (value) {
					smart.classroomControl.enablePictogramsControl();
				} else {
					smart.classroomControl.disablePictogramsControl();
				}
			},
			getPictogramsDisplay:function(){
				return _pictogramsDisplay;
			},

		};
	})();
})(window.smart = window.smart || {});

(function(smart){
	"use strict";
	smart.classroomControlIntegration = (function(){
		var tpl = "";
		var _getContainer = function(){
			var $ret = $$("#"+app.dat.getCurrentPage()+" #page-view-center");
			if (!$ret.length){
				$ret = $$(window.contentWindow);
			}
			return $ret;
		};
		var _getScrollTop = function(){
			var $pageViewCenter = $$("#page-view");
			var fromPoint;
			fromPoint = contentDocument.elementFromPoint($pageViewCenter.width()/2,$pageViewCenter.scrollTop());
			$pageViewCenter.off(".getScrollTop").one("mouseover.getScrollTop",function(e){
				_triggerGoto(e);
			});
			if (fromPoint){
				$$(fromPoint).mouseover();
			}			
		};
		var _getFocusedCompId = function(){
			var $pageViewCenter = $$("#page-view");
			var fromPoint;
			fromPoint = contentDocument.elementFromPoint($pageViewCenter.width()/2,  $pageViewCenter.offset().top + 10);
			$pageViewCenter.off(".getFocusedCompId").one("mousedown.getFocusedCompId",function(e){
				_triggerGoto(e);
			});
			if (fromPoint){
				$$(fromPoint).mousedown();
			}		
		};
		var _triggerGoto = function(e){
			var $target = $(e.target);
			var compId = $target.closest("[data-comp-name]").attr("id");
			if(!!app.dat.closestByProperty(compId,"quizActivity","quizActivity")){
				compId = app.dat.closestByProperty(compId,"quizActivity","quizActivity");
			}		
			e.stopPropagation();
			e.preventDefault();
			if(compId){
				smart.eventBus.trigger("classroomControl:goto",{
					"id": compId,
					"page": app.dat.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
			}
		};
		var _gotoPoint = function(){
			$$("html").off("._integrationGotoPoint").one("click._integrationGotoPoint", ".ntx-comp", function(e){
				_triggerGoto(e);
				smart.eventBus.trigger("classroomControl:onGotoPoint");
				$$("body").css("cursor","default");
			});
		};
		var _onMasterInserted = function(id){
			if(smart.classroomControl.isEnableLock() || smart.classroomControl.isEnableBlockStudents()){
				smart.eventBus.trigger("classroomControl:goto",{
					"id": id,
					"page": app.dat.getCurrentPage(),
					"unitUri": smart.scaResponse.get("unitUri")
				});
			}
		};
		var _onPictogramsDisplayChange = function(e){
			if(smart.classroomControl.isEnabledPictogramsControl() && smart.classroomControl.getPictogramsDisplay() !== e.mode && smart.scaResponse.isTeacherOrCoteacher()) {
				smart.eventBus.trigger("classroomControl:changePictogramsDisplay", e);
			}
		};
		/* var _sendMediaEvent = function(type,e){
			if (smart.classroomControl.isEnableLock()  || smart.classroomControl.isEnableBlockStudents()){
				e.type = type;
				smart.eventBus.trigger("classroomControl:sendMediaEvent",e);
			}
		}; */
		var _disableGotoPoint = function(){
			$$("html").off("._integrationGotoPoint");
		};
		var _currentElementChange = function(type,id){
			if (smart.classroomControl.isEnableLock() || smart.classroomControl.isEnableBlockStudents()){
				var obj = {
					"id":id,
					"page": app.dat.getCurrentPage(),					
					"type":type,
					"unitUri": smart.scaResponse.get("unitUri")
				};
				smart.eventBus.trigger("classroomControl:currentElementChange",obj);
			}
		};
		var _updateinterface = function() {
			var views = smart.utils.getVal(contentWindow,"ntxTemplateJsonViews.interface.views");
			_.each(views, function(view, key){
				var phtml = view.phtml;
				phtml = phtml.replace(/data-tools-pictogram>/ ,'$& ' + tpl);
				app.templateCache.update('interface', key, phtml);
			});
		};
		var _enablePictogramsControl = function(e) {	
			if(e.currentTarget.checked) {
				smart.classroomControl.togglePictogramsControl(true);
			} else {
				smart.classroomControl.togglePictogramsControl(false);
			}
		};
		var _checkPictogramsdisplay = function(){
			if(smart.scaResponse.get("isTeacher") && smart.classroomControl.isEnabledPictogramsControl()){
				$$(".pictograms-control-container input").attr("checked", true);
			}
		};
		var _init = function(){
			tpl = $("#pictogramsControl").text();
			app.eventBus
				.on("pageContent:inserted", function(e){
					_onMasterInserted(e.id);
				})
				.on("popupSingle:inserted", function(e){
					_onMasterInserted(e.id);
				})
				.on("popupSingle.removed", function(e){
					if (smart.classroomControl.isEnableLock()  || smart.classroomControl.isEnableBlockStudents()){
						smart.eventBus.trigger("classroomControl:closePopup",e);
					}
				})
				/* .on("video.play", function(e){
	                _sendMediaEvent("video.play", e);
				})
				.on("video.pause", function(e){
	                _sendMediaEvent("video.pause", e);
	            })
	            .on("video.seeking", function(e){
	                _sendMediaEvent("video.seeking", e);
	            })
	            .on("audio.play", function(e){
	                _sendMediaEvent("audio.play", e);
	            })
	            .on("audio.pause", function(e){
	                _sendMediaEvent("audio.pause", e);
	            })
	            .on("audio.seeking", function(e){
	                _sendMediaEvent("audio.seeking", e);
				}) */
				.on("quiz:currentActivityChange", function(id){
	                _currentElementChange("currentActivityChange", id);
				})
				.on("tabs:currentTabChange", function(e){
					if(e.prevId !== null && e.prevId !== e.id){
						_currentElementChange("currentTabChange", e.id);
					}	
				})
				.on("accordion:currentAccordionChange", function(id){
	                _currentElementChange("currentAccordionChange", id);
				})
				.on("screen:changed", function(id){
	                _currentElementChange("currentScreenChange", id);
				})
				.on("smart:changePictogramDisplay", function(e){
					_onPictogramsDisplayChange(e);
				})
				.off("interface:inserted", _checkPictogramsdisplay).on("interface:inserted", _checkPictogramsdisplay )
				;
				
				_updateinterface();
				$$("html").on("change", ".pictograms-control-container input[type='checkbox']", _enablePictogramsControl);

			smart.eventBus.trigger("moduleLoaded","classroomControlIntegration");
		};
		return {
			require: ["integration","eventBus","stomp","localStorage","classroomControl"],
			init:function(){
				_init();
			},
			guidedOn: function(){
				_getContainer().scrollEnd(function(){
					_getScrollTop();
				}, 200);
			},
			guidedOff: function(){
				_getContainer().scrollEnd(null, 0);
			},
			gotoPoint:function(){
				_gotoPoint();
			},
			disableGotoPoint: function(){
				_disableGotoPoint();
			},
			getCurrentPage:function(){
				return app.dat.getCurrentPage();
			},
			getCurrentPopup:function(){
				return app.dat.getCurrentPopup();
			},
			getFocusedCompId:function(){
				_getFocusedCompId();
			},
			triggerGoto: function(e){
				_triggerGoto(e);
			}
		};
	})();
})(window.smart = window.smart || {});

(function(smart){
	"use strict";
	smart.classroomControlListen = (function(){
		var _init = function(){
			smart.stomp.send("teacher", "classroomControlListen:isEnabled");		
			smart.classroomControlListenIntegration.dispatching();
			smart.eventBus.trigger("moduleLoaded","classroomControlListen");
		};
		return {
			require: ["eventBus","stomp","student","classroomControlListenIntegration"],
			init:function(){
				_init();
			}
		};
	})();
})(window.smart = window.smart || {});
(function (smart) {
	"use strict";
	smart.classroomControlListenIntegration = (function () {
		var _enabledPictogramsControl = false;
		var _pictogramsDisplay = "image";
		var _init = function () {
			var _classroomControlOn = false;
			var _classroomLookOn = false;
			var _classroomBlockStudentsOn = false;
			
			smart.eventBus
				.on("offlineMode", function () {
					smart.eventBus.off("integration:hashchange");
					app.eventBus.on("pageContent:inserted", function () {
						app.api.enableRouter();
					});
					$("body").removeClass("ntx-guided-navigation-blocker");
					$("#guided-navigation-blocker").off("_classroomcontrol");
					_classroomControlOn = false;
					_classroomLookOn = false;
					_classroomBlockStudentsOn = false;
				})
				.on("stomp:onStudentNotification:authoringUpdated", function(){
					app.eventBus.off("interface:inserted", _checkPictogramsdisplay);
					app.eventBus.on("interface:inserted", _checkPictogramsdisplay );
				})
				.on("stomp:onStudentNotification:classroomControl:goto", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						if (e.page !== app.dat.getCurrentPage() && e.page !== e.id) {			
							app.router.index(e.id);							
						}else{
							app.router.gotoId(e.id);							
						}
					}
				})
				.on("stomp:onStudentNotification:classroomControl:lock:on", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						if (e.id !== app.dat.getCurrentPage()) {
							app.router.index(e.id);
							app.eventBus.on(e.id + ":navigate", function(){
								app.api.disableRouter();
								smart.eventBus.trigger("stomp:onStudentNotification:classroomControl:lock:on:delay", e);
							})
						} else {
							app.api.disableRouter();
							smart.eventBus.trigger("stomp:onStudentNotification:classroomControl:lock:on:delay", e);
						}
						_classroomLookOn = true;
					}
				})
				.on("stomp:onStudentNotification:classroomControl:lock:off", function (e) {
					if (_classroomLookOn) {
						if (e.unitUri === smart.scaResponse.get("unitUri")) {
							app.api.enableRouter();
							_classroomLookOn = false;
							app.eventBus.off(e.id + ":navigate");
						}
					}
				})
				.on("stomp:onStudentNotification:classroomControl:blockStudents:on", function(e){
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						if (e.id !== app.dat.getCurrentPage()) {
							app.router.index(e.id);
							_.defer(function () {
								app.api.disableRouter();
								smart.eventBus.trigger("studentsNavigationBlockerView001:show");
							});
						} else {
							app.api.disableRouter();
							smart.eventBus.trigger("studentsNavigationBlockerView001:show");
						}
						_classroomBlockStudentsOn = true;						
					}
				})
				.on("stomp:onStudentNotification:classroomControl:blockStudents:off", function(e){
					if(_classroomBlockStudentsOn){
						if (e.unitUri === smart.scaResponse.get("unitUri")) {
							smart.eventBus.trigger("studentsNavigationBlockerView001:hide");
							app.api.enableRouter();
							_classroomBlockStudentsOn = false;
						}
					}
				})
				.on("stomp:onStudentNotification:classroomControl:closePopup", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						app.router.gotoId(app.dat.getCurrentPage());
					}
				})
				.on("stomp:onStudentNotification:classroomControl:sendMediaEvent", function (e) {
					var inst = app.compController.getInstanceById(e.id);
					if (inst) {
						if (e.unitUri === smart.scaResponse.get("unitUri")) {
							if (e.type === "video.play") {
								inst.objVideo.setCurrentTime(e.currentTime);
								inst.objVideo.play();
							}
							if (e.type === "video.pause") {
								inst.objVideo.pause();
							}
							if (e.type === "video.seeking") {
								inst.objVideo.setCurrentTime(e.currentTime);
							}
							if (e.type === "audio.play") {
								inst.objAudio.setCurrentTime(e.currentTime);
								inst.objAudio.play();
							}
							if (e.type === "audio.pause") {
								inst.objAudio.pause();
							}
							if (e.type === "audio.seeking") {
								inst.objAudio.setCurrentTime(e.currentTime);
							}
						}
					}
				})
				.on("stomp:onStudentNotification:classroomControl:currentElementChange", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						//if(e.page === app.dat.getCurrentPage()){
							if (e.type === "currentAccordionChange") { //accordion case
								contentWindow.location.hash = "#" + app.dat.closest(e.id, "accordion");
								$$("#" + e.id + " .ntx-accordionItem-header").click();
							} else {
								_.delay(function(){
									app.router.gotoId(e.id);
								},500);
							}						
						//}
					}
				})
				.on("integration:hashchange", function () {
					if (_classroomLookOn) {
						smart.eventBus.trigger("smart:toastNotification", {
							"duration": 2200,
							"type": "Error",
							"text": smart.translates.get("lock_notification")
						});
					} 
				})
				.on("stomp:onStudentNotification:classroomControl:pictogramsControl:on", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						$$('[data-interface-btn="pictogramDisplay"]').attr('disabled', true);
						$$('[data-tools-pictogram]').removeClass("visible");
						app.eventBus.trigger("smart:onChangePictogramsDisplay", {
							"mode": e.mode
						});
						_enabledPictogramsControl = true;
						_pictogramsDisplay = e.mode;
					}
				})
				.on("stomp:onStudentNotification:classroomControl:pictogramsControl:off", function (e) {
					if(_enabledPictogramsControl){
						if (e.unitUri === smart.scaResponse.get("unitUri")) {
							$$('[data-interface-btn="pictogramDisplay"]').attr('disabled', false);
							app.eventBus.trigger("smart:onChangePictogramsDisplay", {
								"mode": _pictogramsDisplay
							});
							_enabledPictogramsControl = false;
						}
					}
				})
				.on("stomp:onStudentNotification:classroomControl:pictogramDisplay", function (e) {
					if (e.unitUri === smart.scaResponse.get("unitUri")) {
						app.eventBus.trigger("smart:onChangePictogramsDisplay", {
							"mode": e.mode
						});
						_pictogramsDisplay = e.mode;
					}
				})
				;

				//hacer template
			$("body").append('<div id="guided-navigation-blocker" class="guided-navigation-blocker"></div>');
			smart.eventBus.trigger("moduleLoaded", "classroomControlListenIntegration");
			_pictogramsDisplay = smart.scaResponse.get("user").pictogramConfigGroup !== "null" ? smart.scaResponse.get("user").pictogramConfigGroup : "image";
		};
		var _controlIsEnabled = function(){
			smart.stomp.send("teacher", "classroomControlListen:isEnabled");
			smart.stomp.send("student", "classroomControl:pictogramDisplay", {
				"mode": _pictogramsDisplay,
				"unitUri": smart.scaResponse.get("unitUri")
			});
			app.eventBus.off("pageContent:inserted", _controlIsEnabled);
		};
		var _overwriteNavigationFunctions = function() {
			var _oldGoNextFunction = app.api.goNext;
			app.api.goNext = function() {
				smart.eventBus.trigger("integration:hashchange");
				return _oldGoNextFunction();
			};
			var _oldGoPrevFunction = app.api.goPrev;
			app.api.goPrev = function() {
				smart.eventBus.trigger("integration:hashchange");
				return _oldGoPrevFunction();
			};
		};
		var _checkPictogramsdisplay = function() {
				if(_enabledPictogramsControl && !smart.scaResponse.isTeacherOrCoteacher()) {
					app.utils.removeCssClassesStartWith("ntx-pictogram-", $$("body"));
					$$('[data-interface-btn="pictogramDisplay"]').attr('disabled', true);
					$$('[data-tools-pictogram]').removeClass("visible");
					app.eventBus.trigger("smart:onChangePictogramsDisplay", {
						"mode": _pictogramsDisplay
					});
				}
		};
		return {
			require: ["integration", "eventBus", "translates", "scaResponse","student"],
			init: function () {
				_init();
				_overwriteNavigationFunctions();
			},
			dispatching: function () {
				app.eventBus.on("pageContent:inserted", _controlIsEnabled);
			}
		};
	})();
})(window.smart = window.smart || {});
