(function (smart) {
	"use strict";
	smart.copyPasteActivities = (function () {
		var COPIED_ACTIVITY;
		var _catalogData;
		var _init = function () {
			COPIED_ACTIVITY = "copiedActivity_" + smart.scaResponse.get("scaResponseId");
			smart.eventBus
				.on("copyPasteActivities:copyActivity", _copyActivity)
				.on("copyPasteActivities:pasteActivity", _pasteActivity)
				.trigger("moduleLoaded", "copyPasteActivities");
		};

		var _copyActivity = function (obj) {
			var copyActivity = _buildCopyActivity(obj);
			try {
				window.navigator.clipboard.readText();
				window.navigator.clipboard.writeText(JSON.stringify(copyActivity))
					.then(function () {
						smart.eventBus.trigger("smart:toastNotification", {
							type: "Success",
							text: smart.translates.get('copy_activity_message')
						});
					})
					.catch(function (error) {
						console.log(error);
						smart.eventBus.trigger("smart:toastNotification", {
							type: "Error",
							text: smart.translates.get('copy_activity_error_message')
						});
					});
			} catch (error) {
				smart.localStorage.setItem(COPIED_ACTIVITY, JSON.stringify(copyActivity));
				smart.eventBus.trigger("smart:toastNotification", {
					type: "Success",
					text: smart.translates.get('copy_activity_message')
				});
			}
		};

		var _pasteActivity = function (obj) {
			var copiedActivity;
			try {
				window.navigator.clipboard.readText().then(function (text) {
					copiedActivity = JSON.parse(text);
					if (copiedActivity && copiedActivity.data && copiedActivity.compId && obj.refId && copiedActivity.activityId) {
						smart.editorActivities.importActivity(copiedActivity.data, copiedActivity.compId, obj.refId, copiedActivity.activityId);
						smart.eventBus.trigger("smart:toastNotification", {
							type: "Success",
							text: smart.translates.get('paste_activity_message')
						});
					} else {
						smart.eventBus.trigger("smart:toastNotification", {
							type: "Error",
							text: smart.translates.get('paste_activity_error_message')
						});
						smart.eventBus.trigger("editor:onFailPaste");
					}
				}).catch(function (error) {
					smart.eventBus.trigger("smart:toastNotification", {
						type: "Error",
						text: smart.translates.get('paste_activity_error_message')
					});
					smart.eventBus.trigger("editor:onFailPaste");
				});
			} catch (error) {
				copiedActivity = JSON.parse(smart.localStorage.getItem(COPIED_ACTIVITY));
				smart.localStorage.removeItem(COPIED_ACTIVITY);
				if (copiedActivity && copiedActivity.data && copiedActivity.compId && obj.refId && copiedActivity.activityId) {
					smart.editorActivities.importActivity(copiedActivity.data, copiedActivity.compId, obj.refId, copiedActivity.activityId);
					smart.eventBus.trigger("smart:toastNotification", {
						type: "Success",
						text: smart.translates.get('paste_activity_message')
					});
				} else {
					smart.eventBus.trigger("smart:toastNotification", {
						type: "Error",
						text: smart.translates.get('paste_activity_error_message')
					});
					smart.eventBus.trigger("editor:onFailPaste");
				}
			}
		};

		var _buildCopyActivity = function (obj) {
			_catalogData = _.clone(app.dat.getData());
			var clipboardObject = {
				compId: obj.id,
				activityId: smart.integration.getActivityUri(obj.id),
				data: {}
			};
			clipboardObject["data"][obj.id] = _catalogData[obj.id];
			var children = _catalogData[obj.id].componentsTreeIds || smart.utils.getChildIds(obj.id, _catalogData);
			children.forEach(function (child) {
				clipboardObject["data"][child] = _catalogData[child];
			});
			if (!(_catalogData[obj.id].componentsTreeIds)) {
				var linkedComps = _getLinkedComps(clipboardObject.data, _catalogData);
				Object.assign(clipboardObject.data, linkedComps);
			}
			for (var element in clipboardObject["data"]) {
				if (clipboardObject["data"][element].hasOwnProperty("componentName") && clipboardObject["data"][element].hasOwnProperty("parentId")) {
					clipboardObject["data"][element]["name"] = clipboardObject["data"][element]["componentName"];
					clipboardObject["data"][element]["parent"] = {};
					clipboardObject["data"][element]["parent"]["id"] = clipboardObject["data"][element]["parentId"];
				}
			}
			return clipboardObject;
		};

		var _getLinkedComps = function (authoringLesson, authoringObject) {
            var linkedComps = Object.entries(authoringLesson).reduce(function (acc, value) {
                var processCompId = function (id) {
                    if (authoringObject[id]) {
                        acc[id] = authoringObject[id];
                        var children = smart.utils.extractComponentChildrenIds(id, []);
                        children.forEach(function (child) {
                            acc[child] = authoringObject[child];
                        });
                    }
                };
                var htmlProperties = app.edat.getHtmlProperties(app.dat.getCompName(value[1].id));
                if (htmlProperties.length) {
                    htmlProperties.forEach(function (property) {
                        var string = '<div>' + value[1].properties[property] + '</div>';
                        var $content = $(string);
						$content.find("[data-pictogram-wrap]").each(function () {
							var pictogramWrapId = $(this).data("pictogram-wrap");
							if (pictogramWrapId.includes("_")) {
								pictogramWrapId = pictogramWrapId.split("_")[0];
							}
							processCompId(pictogramWrapId);
						});
                    });
                }
                return acc;
            }, {});
            return linkedComps;
        };

		return {
			require: ["eventBus", "editorIntegration"],
			init: function () {
				_init();
			}
		};
	})();
})(window.smart = window.smart || {});
(function (smart) {
    "use strict";
    smart.editor = (function () {
        var _enable = false;
        //var _authoring;
        var _init = function () {
            smart.eventBus
                .on("smart:view:editor:toggle", _toggle)
                .on("editor:enable:false", smart.editor.sync)
                .on("stomp:reconnecting", _disableEditor)
                .on("stomp:disconnected", _disableEditor)
                .trigger("moduleLoaded", "editor");
        };
        var _toggle = function () {
            (smart.editor.isEnable() ? smart.editor.disable : smart.editor.enable)();
        };
        var _setEnable = function (value) {
            if (value !== _enable) {
                _enable = value;
                smart.eventBus.trigger("editor:enable:" + value);
            }
        };
        var _disableEditor = function () {
            if (smart.editor.isEnable()) {
                smart.eventBus.trigger("smart:view:editor:toggle");
            }
        };
        var _componentsEditables = function (data) {
            var originalComponents = _.keys(data);
            var noEditablesComponents = _.pick(app.dat.getData(), function (v, k) {
                // if (!app.dat.closest(k,"quiz")){
                if (!app.dat.closestByProperty(k, "quizActivity", "quizActivity") && !app.dat.closest(k, 'activityNoInteractive')) {
                    return false;
                }
                return _.contains(originalComponents, k);
            });
            _.each(noEditablesComponents, function (v) {
                data[v.id].readOnly = true;
            });
            return data;
        };
        return {
            require: ["eventBus", "state_or_teacher", "scaResponse", "http", "editorIntegration", "cmi5", "integration", "stomp"],
            init: function () {
                _init();
            },
            sync: function () {
                $("#mainView001").find((".main-view-001-spinner")).show();
                $("[data-require-module='editor']").prop( "disabled", true );
                smart.editorActivities.unbindMultipleChoiceOption();
                var data = _componentsEditables(smart.editorIntegration.getChangesData());
                var currentPage = smart.editorIntegration.getCurrentPage();
                var images = _.reduce(data, function (m, v, k) {
                    if (v.name === "image") {
                        m[k] = {
                            "id": k,
                            "uuid": smart.utils.getVal(v, "extendedProperties.srcName.uuid"),
                            "url": smart.utils.getVal(v, "extendedProperties.srcName.url")
                        };
                    }
                    return m;
                }, {});
                smart.cmi5.updateById(currentPage, data, images);
                smart.undoRedoIntegration.setMemento();
            },
            enable: function () {
                _setEnable(true);
            },
            disable: function () {
                _setEnable(false);
            },
            isEnable: function () {
                return _enable;
            },
            uploadImage: function (self, id) {
                var file = $$(self)[0].files[0];
                var val = $$(self).val();
                var url = smart.scaResponse.get("assetPresignService");
                var url2 = smart.scaResponse.get("assetService");
                var conf = smart.scaResponse.get("configuration");
                $$("#smartLoader_" + id).addClass("loader");
                setTimeout(function () {
                    var fileExtension = val.substring(val.lastIndexOf('.') + 1).toLowerCase();
                    switch (fileExtension) {
                        case 'gif':
                        case 'jpg':
                        case 'jpeg':
                        case 'png':
                        case 'svg':
                            if (conf.maxUploadSize >= Math.round((file.size) / 1024 / 1024)) {
                                var fnString = '' + smart.utils.getUUID() + '.' + fileExtension;
                                    axios.get(url + "?fileName=" + fnString + "&assetType=SMART_ASSET").then(function(preSignedRequest){
                                        var uploadData = new FormData();
                                        var isBodyExtended = Object.keys(preSignedRequest.data.body).length > 0;
                                        if(isBodyExtended){
                                            var keysObj = Object.keys(preSignedRequest.data.body);
                                            var valuesObj = Object.values(preSignedRequest.data.body);
                                            for(var i = 0; i < keysObj.length; i++){
                                                uploadData.append(keysObj[i], valuesObj[i]);
                                            }
                                            uploadData.append('file', file, fnString);
                                        } else {
                                            Object.defineProperty(file, 'name', {
                                                writable: true,
                                                value: fnString
                                            });
                                        }
                                        axios({
                                            url: preSignedRequest.data.url,
                                            method: preSignedRequest.data.method,
                                            headers: preSignedRequest.data.headers,
                                            data:  isBodyExtended ? uploadData : file,
                                            preventInterceptors: true
                                        }).then(function () {
                                            var payload = {
                                                uuid: preSignedRequest.data.uuid,
                                                fileName: fnString,
                                                assetType: "SMART_ASSET",
                                                mimeType: file.type
                                            };
                                            return axios.post(url2, payload).then(function (res) {

                                                $$("#smartLoader_" + id).removeClass("loader");
                                                var newId = smart.editorIntegration.editor("addImage", {
                                                    "id": id,
                                                    "uuid": res.data.uuid,
                                                    "imageUrl": res.data.url
                                                });
                                                smart.eventBus.trigger("editor:uploadImage", {
                                                    "id": id
                                                });
                                                _.defer(function () {
                                                    app.compController.redraw(newId);
                                                });
                                            });
                                        });
                                    }).catch(function (error) {
                                    $$("#smartLoader_" + id).removeClass("loader");
                                    if (error.response.status === 413) {
                                        smart.eventBus.trigger("smart:toastNotification", {
                                            type: "Error",
                                            text: smart.translates.get("error_upload_size_img"),
                                            duration: 5000
                                        });
                                    } else {
                                        smart.eventBus.trigger("smart:toastNotification", {
                                            type: "ERROR",
                                            text: smart.translates.get("error_upload_img")
                                        });
                                    }
                                    //console.log("uploadFile fail: ", error.response);
                                });
                            } else {
                                $$("#smartLoader_" + id).removeClass("loader");
                                smart.eventBus.trigger("smart:toastNotification", {
                                    type: "Error",
                                    text: smart.translates.get("error_upload_size_img"),
                                    duration: 5000
                                });
                            }
                            break;
                        default:
                            $$("#smartLoader_" + id).removeClass("loader");
                            smart.eventBus.trigger("smart:toastNotification", {
                                type: "ERROR",
                                text: smart.translates.get("not_supported_image")
                            });
                            //console.log("not_supported_image");
                            break;
                    }
                }, 3000);
            },
            importFromCatalog: function (path, id) {
                var fileExtension = path.split('/').pop().toLowerCase().split('.').pop();
                var newId;
                switch (fileExtension) {
                    case 'gif':
                    case 'jpg':
                    case 'jpeg':
                    case 'png':
                    case 'svg':
                        newId = smart.editorIntegration.editor("addImage", {
                            "id": id,
                            "imageUrl": '../' + path
                        });
                        _.defer(function () {
                            app.compController.redraw(newId);
                        });
                        break;
                    case 'mp4':
                        newId = smart.editorIntegration.editor("addVideo", {
                            "id": id,
                            "url": '../' + path
                        });
                        _.defer(function () {
                            app.compController.redraw(newId);
                        });
                        break;
                    default:
                        smart.eventBus.trigger("smart:toastNotification", {
                            type: "ERROR",
                            text: smart.translates.get("not_supported_image")
                        });
                        break;
                }
            }
        };
    })();
}

)(window.smart = window.smart || {});


