					setCorrectCssClasses: function (id) {
						if (app.dat.getCompName(id) === "qSmartTapTapTarget") {
							var target = id;
							var parentId = app.dat.closestByProperty(id, "quizActivity");
							var origin = _.findKey(app.dat.getActivitySolution(parentId), { "value": target }) || _.findKey(app.dat.getActivitySolution(parentId), { "value": "false" });
						} else {
							var target = app.utils.getVal(app.dat.getCompById(id), "properties.correct");
							var origin = id;
						}

						smart.utils.removeCssClassesStartWith("ntx-qTapTapTarget-ordinal-", $$("#" + target));
						smart.utils.removeCssClassesStartWith("ntx-qTapTapOrigin-position-", $$("#" + origin));
						$$("#" + origin).removeClass("ntx-correct ntx-qTapTapOrigin-linked");

						if (app.utils.getVal(app.dat.getCompById(origin), "properties.correct") !== "false") {
							$$("#" + origin).addClass("ntx-correct ntx-qTapTapOrigin-linked");
							$$("#" + origin).addClass("ntx-qTapTapOrigin-position-" + (app.dat.getPositionInSiblings(origin).position + 1));
							$$("#" + target).addClass("ntx-correct ntx-qTapTapTarget-linked ntx-qTapTapTarget-ordinal-" + (app.dat.getPositionInSiblings(origin).position + 1));
							var instOrigin = app.compController.getInstanceById(origin);
							instOrigin.$el.off("click." + origin, instOrigin._bind("onElClick"));
							var instTarget = app.compController.getInstanceById(target);
							instTarget.$el.off("click." + target, instTarget._bind("onElClick"));
						}

					},
