(function (smart) {
    "use strict";
    smart.floatingBar = (function () {
        var _loaded = false;

        var _init = function () {
            $("#catalogPictogramButton").on("click", function () {
                smart.eventBus.trigger("smart:view:panelCatalog:toggle", undefined, {
                    mimeTypeDefaultValue: "pictogram",
                    fixedResourceType: "file"
                });
                $('#catalogPictogramButton').hide();
            });

            $$("#page-view").on("mouseup", function () {
                // This code is embedded in a setTimeout because the text deselection in UI happens after the mouseup event,
                // so we need to wait for it to happen before checking if there is a selected text
                setTimeout(function () {
                    var selectedText = getSelectedText();

                    if (selectedText) {
                        const $selectedElement = $(window.contentWindow.getSelection().anchorNode);
                        const $ntxTextComponent = $selectedElement.closest('.ntx-text');
                        const $ckEditorElement = $selectedElement.closest('[id^="ck_"]');
                        if (
                            // If the current content supports pictograms
                            app.utils.getVal(app.dat.getCompsByName('interface')[0], "properties.showPictograms", "false") === "true" &&
                            // If the selected text is not considered unmodifiable by the application
                            $ntxTextComponent.length && !_.contains(app.edat.getEditorTextOmitIds(), $ntxTextComponent.attr('id')) &&
                            // If ckeditor can be shown (same use case as show catalog button)
                            app.edat.getEditorTextEnable() && $ckEditorElement.length && !$ckEditorElement.is("span") && !$ckEditorElement.hasClass('ntx-has-pictograms')
                        ) {
                            var selection = window.contentWindow.getSelection();
                            var range = selection.getRangeAt(0);
                            var rect = range.getBoundingClientRect();

                            $('#catalogPictogramButton').css({
                                'position': 'absolute',
                                'display': 'block',
                                'top': rect.bottom + window.contentWindow.scrollY,
                                'left': rect.left + window.contentWindow.scrollX,
                            });
                        }
                    } else {
                        $('#catalogPictogramButton').hide();
                    }
                }, 0);
            });

            // When a text is inserted, we need to create the pictogram events
            app.eventBus.on("text:inserted", function (e) {
                // Remove the previous events to avoid duplicates
                _.each($$("#" + e.id).find("[data-pictogram-wrap]"), function (element) {
                    $$(element).off("click");
                });
                var instance = app.compController.getInstanceById(e.id);
                instance.createPictogramEvents();
            });

            // If user clicks out of the pictogram, close the pictogram popup
            $$("#page-view").on('click', function (event) {
                var $target = $(event.target);
                if (!$target.closest('.ntx-pictogram-573-001-wrap').length && !$target.hasClass('ntx-tooltip')) {
                    closeAllPopups();
                }
            });

            // The bar will disappear if the user moves the mouse too far away from it
            $$("#page-view").mousemove(function (event) {
                var elemOffset = $("#catalogPictogramButton").offset();
                var topDist = event.pageY - elemOffset.top;
                var bottomDist = ($("#catalogPictogramButton").outerHeight() + elemOffset.top) - event.pageY;

                var verticalDistanceLimit = 50;
                if (topDist < -verticalDistanceLimit || bottomDist < -verticalDistanceLimit) {
                    $('#catalogPictogramButton').hide();
                }
            })

            function closeAllPopups() {
                $$(".ntx-pictogram-text-container, .ntx-pictogram-image-container").each(function () {
                    $(this).removeClass("ntx-tooltip");
                    $(this).css({
                        "display": "",
                        "top": "",
                        "left": ""
                    });
                });
            }

            function getSelectedText() {
                var text = "";
                if (typeof window.contentWindow.getSelection != "undefined") {
                    text = window.contentWindow.getSelection().toString();
                } else if (typeof document.selection != "undefined" && document.selection.type == "Text") {
                    text = document.selection.createRange().text;
                }
                return text.trim();
            }

            _sendLoaded();
        }

        var _sendLoaded = function () {
            if (!_loaded) {
                smart.eventBus.trigger("moduleLoaded", "floatingBar");
                _loaded = true;
            }
        };

        return {
            require: ["integration"],
            init: _init
        };
    })();
})(window.smart = window.smart || {});

(function (smart) {
	"use strict";
	smart.highlight = (function () {
		var $el;
		var _highlighter;
		var _unitHighlights = [];
		var _serialize;
		var _rangy;
		var _init = function () {
			_rangy = contentWindow.rangy;
			$el = $("[highlight-btns]");
			$el.on("click", "#highlight-btns_mark", function (e) {
				_mark(e, "mark");
			});
			$el.on("click", "#highlight-btns_unmark", function (e) {
				_unmark(e, "unmark");
			});

			_rangy.init();
			_highlighter = _rangy.createHighlighter();
			_highlighter.addClassApplier(_rangy.createClassApplier("highlight"));
			_getHighlights();
			smart.eventBus.trigger("moduleLoaded", "highlight");
			app.eventBus.on("pageContent:inserted", _setSerialize);
			app.eventBus.on("component:inserted", _reload);
		};


		var _updateHighlight = function () {
			if (_serialize != _highlighter.serialize()) {
				var url = smart.scaResponse.get("highlightsService");
				var payload = {
					bookActivityId: smart.scaResponse.get("bookUri"),
					unitActivityId: smart.scaResponse.get("unitUri"),
					pageId: app.dat.getCurrentPage(),
					serialize: _highlighter.serialize(),
				};
				smart.http.post("highlight", url, payload);
				_updateUnitHighlights();
				$el.find("#highlight-btns_mark").toggleClass("active", false);
				$el.find("#highlight-btns_unmark").toggleClass("active", false);
			}
		};

		var _mark = function () {
			if (!_rangy.getSelection().isCollapsed) {
				_highlighter.highlightSelection('highlight');
				_rangy.getSelection().removeAllRanges();
				_updateHighlight();
			}
		};

		var _unmark = function () {
			if (!_rangy.getSelection().isCollapsed) {
				_highlighter.unhighlightSelection();
				_updateHighlight();
			}
		};

		var _getHighlights = function () {
			_unitHighlights = smart.highlightIntegration.getHighlights();
		};

		var _updateUnitHighlights = function () {
			var update = false;
			for (var i = 0; i < _unitHighlights.length; i++) {
				if (_unitHighlights[i].pageId === app.dat.getCurrentPage()) {
					_unitHighlights[i].serialize = _highlighter.serialize();
					update = true;
				}
			}
			if (!update) {
				_unitHighlights.push({
					"serialize": _highlighter.serialize(),
					"pageId": app.dat.getCurrentPage()
				});
			}
			_serialize = _highlighter.serialize();
		};

		var _setSerialize = function () {
			var serialize;
			for (var i = 0; i < _unitHighlights.length; i++) {
				if (_unitHighlights[i].pageId === app.dat.getCurrentPage()) {
					serialize = _unitHighlights[i].serialize;
				}
			}
			if (!serialize) {
				serialize = "type:textContent";
			}
			_serialize = serialize;
			_highlighter.deserialize(_serialize);
		};

		var _reload = _.throttle(function () {
			_highlighter.deserialize(_highlighter.serialize());
		}, 500);

		return {
			require: ["eventBus", "integration", "highlightIntegration", "student", "highlightView001", "scaResponse", "http"],
			init: function () {
				_init();
			}
		};
	})();
})(window.smart = window.smart || {});

