(function (smart) {
  "use strict";
  smart.state = (function () {
    var _state = null;
    var _saveState;
    var _currentUser;
    var _init = function () {
      _currentUser = smart.scaResponse.get("scaResponseId");
      _saveState = "saveState_" + _currentUser;
      if (!window.navigator.onLine) {
        _setStateFromLocal();
      }
      smart.eventBus
        .on("http:disconnected", _setStateFromLocal)
        .on("http:queuePostSendFromLocal", _setState)
      ;
    };
    var _setState = function () {
      smart.http.get(smart.scaResponse.get("activityTrackingService")).then(function (res) {
        _state = _createState(res.data);
        smart.eventBus.trigger("moduleLoaded", "state");
      }).catch(function () {
        _state = JSON.parse(smart.localStorage.getItem(_saveState));
        smart.eventBus.trigger("moduleLoaded", "state");
      });
    };
    var _setStateFromLocal = function () {
      _state = JSON.parse(smart.localStorage.getItem(_saveState));
      smart.eventBus.trigger("moduleLoaded", "state");
    };

    var _createState = function (data) {
      var id;
      var models = {};
      _.each(data, function (act) {
        var status;
        var mode;
        var incorrectAreas = [];
        var finished;
        var current;
        var popupType;
        var time;
        var timerType;
        id = act.activityId.split("/").pop();
        if (act.result) {
          var response = act.result.response;
          var score = act.result.score ? act.result.score.raw : 0;
          }
        if (act.ntxModelJson){
          mode = act.ntxModelJson.mode;
          status = act.ntxModelJson.status;
          incorrectAreas = act.ntxModelJson.incorrectAreas ? JSON.parse(act.ntxModelJson.incorrectAreas) : [];
          finished = act.ntxModelJson.finished ? act.ntxModelJson.finished : false;
          current = act.ntxModelJson.current;
          popupType = act.ntxModelJson.popupType;
          time = act.ntxModelJson.time ? act.ntxModelJson.time : 0;
          timerType = act.ntxModelJson.timerType ? act.ntxModelJson.timerType : 'none';
        }
        // TODO cuando finalice el curso 2019-2020 y se eliminen las trazas se puede borrar el switch, sÃ³lo se usa para las trazas antiguas
        if (typeof mode === "undefined") {
        switch (act.status.split("/").pop()) {
          case "failed":
            status = "F";
            mode = "checked";
            break;
          case "passed":
            status = "P";
            mode = "checked";
            break;
          case "answered":
            status = "C";
            mode = "checked";
            break;
          case "watch":
            status = "N";
            mode = "doingN";
            break;
          case "initialized":
            status = "N";
            mode = "doingN";
            break;
          case "interacted":
            status = "I";
            mode = "doingI";
            break;
          default:
            status = "N";
            break;
        }
      }
        //
        if(response && JSON.parse(response).suspend){
          models[id] = {
            "cmi.suspend_data": JSON.parse(response).suspend || "{}",
            "mode": mode,
            "status": status,
            "score": score,
          };
        }else{
          models[id] = {
            "response": response || "{}",
            "attempt": act.attempt,
            "score": score,
            "status": status,
            "mode": mode,
            "incorrectAreas": incorrectAreas,
            "finished" : finished,
            "current" : current,
            "popupType" : popupType,
            "time" : time,
            "timerType" : timerType,
            "options": response ? JSON.parse(response) : []
          };
        }
      });
      return {"m": models};
    };
    
    //guarda suspend de maker en localStorage
    var _setLocalState = function (state) {
      var localState = JSON.stringify(state);
      smart.localStorage.setItem(_saveState, localState);
    };

    return {
      require: ["http", "eventBus", "scaResponse", "student", "localStorage"],
      init: function () {
        _init();
      },
      get: function () {
        return _state;
      },
      setLocalState: function (state) {
        _setLocalState(state);
      },
      createState: function (data) {
        return _createState(data);
      }
    };
  })();
})(window.smart = window.smart || {});

