(function (smart) {
  "use strict";
  smart.statements = (function () {
    var smartEventVersionURLParameter = parseInt(smart.utils.getURLParameter('smartEventVersion'));
    var xapiVersionURLParameter = parseInt(smart.utils.getURLParameter('xAPIStatementVersion'));
    var _smartEventVersion = !isNaN(smartEventVersionURLParameter) ? smartEventVersionURLParameter : 2;
    var _xAPIStatementVersion = !isNaN(xapiVersionURLParameter) ? xapiVersionURLParameter : 2;
    console.log('SmartEventVersion: %s', _smartEventVersion);
    console.log('xAPIStatementVersion: %s', _xAPIStatementVersion);
    var _init = function () {
      smart.eventBus.trigger("moduleLoaded", "statements");
      smart.eventBus.on("statement", _onStatement);
    };
    var getAttemptId = function (smartEvent) {
      var attemptId = smartEvent.attemptId;
      if (attemptId === undefined && _smartEventVersion === 2) attemptId = smartEvent.attempt ? smartEvent.attempt.id : 'statementsWithoutAttempt';
      return attemptId;
    };
    var _saveSmartEventToLocalStorage = function (smartEvent) {
      var attemptId = getAttemptId(smartEvent);
      console.log('Saving smart event to localStorage (key %s)', attemptId);
      var a = smart.localStorage.getItem(attemptId);
      a = a ? JSON.parse(a) : [];
      smart.localStorage.setItem(attemptId, JSON.stringify(_.union(a, [smartEvent])));
    };
    var _removeSmartEventFromLocalStorage = function (attemptId, id, type) {
      smart.localStorage.removeItem(attemptId);
      if (id && type) {
        var localStorageKeys = _.keys(window.localStorage);
        _.each(localStorageKeys, function (v) {
          if (v.indexOf("smart_statement_" + id) !== -1) {
            if (type !== "firstResponse") {
              smart.localStorage.removeItem(v);
            }
          }
        });
      }
    };
    var _getSmartAudioVideoEventTypeArray = function () {
      return ["videoPlay", "audioPlay", "videoPause", "audioPause", "videoSeeked", "audioSeeked", "videoSeeking", "audioSeeking", "videoComplete", "audioComplete"];
    };
    var _isSmartAudioVideoEvent = function (eventType) {
      return _.indexOf(_getSmartAudioVideoEventTypeArray(), eventType) !== -1;
    };
    var _isSmartFinalBudgetEvent = function (eventType) {
      return eventType === "checked";
    };
    var _onStatement = function (templateEvent) {
      var smartEvent = _prepareSmartEvent(templateEvent);
      var attemptId = getAttemptId(smartEvent);
      if (_isSmartFinalBudgetEvent(smartEvent.typeEvent)) _saveSmartEventToLocalStorage(smartEvent);
      var smartEventsArray = _isSmartFinalBudgetEvent(smartEvent.typeEvent) ? JSON.parse(smart.localStorage.getItem(attemptId)) : [smartEvent];
      _sendSmartEventsToXAPIEndpoint(smartEventsArray, function (err) {
        if (!err) _removeSmartEventFromLocalStorage(attemptId, templateEvent.id, templateEvent.type);
      });
    };
    var _getContext = function (id) {
      var currentLesson = smart.scaResponse.get("currentLesson");
      currentLesson = currentLesson.substring(0, currentLesson.lastIndexOf("/") + 1);
      currentLesson = currentLesson + smart.statementsIntegration.getCurrentPage(id);
      return {
        "bookUri": smart.scaResponse.get("bookUri"),
        "unitUri": smart.scaResponse.get("unitUri"),
        "sectionId": smart.scaResponse.get("sectionId"),
        "userId": smart.scaResponse.get("userId"),
        "role": smart.scaResponse.isTeacherOrCoteacher() ? "teacher" : "student",
        "tenantId": smart.scaResponse.get("tenantId"),
        "lessonUri": currentLesson
      };
    };
    var _getSmartBaseEvent = function (templateEvent) {
      var context = _getContext(templateEvent.id);
      return {
        "context": context,
        "componentId": templateEvent.id,
        "activityId": smart.integration.getActivityUri(templateEvent.id),
        "typeActivity": templateEvent.typeActivity,
        "mode": templateEvent.mode,
        "status": templateEvent.status,
        "typeEvent": templateEvent.type
      };
    };
    var _getSmartV1EventProperties = function () {
      return {
        "attemptId": templateEvent.attemptId,
        "sequence": templateEvent.sequence,
        "data": templateEvent.data
      };
    };
    var _getSmartXAPIDataProperty = function (templateEvent) {
      var xapiData = {
        timestamp: templateEvent.data.timestamp ? templateEvent.data.timestamp : Date.now(),
        sequenceNumber: templateEvent.sequence
      };
      switch (templateEvent.type) {
        case "response":
        case "checked":
          if (templateEvent.data.componentName === "passWordGame") {
            xapiData.response = templateEvent.data.data.options;
          } else {
            xapiData.response = templateEvent.data.data.response;
          }
          xapiData.status = templateEvent.status;
          break;
        case "firstResponse":
          if (templateEvent.data.componentName === "passWordGame") {
            xapiData.response = templateEvent.data.data.options;
          } else {
            xapiData.response = templateEvent.data.data.response;
          }
          break;
        case "videoPlay":
        case "audioPlay":
          xapiData.startingPoint = templateEvent.currentTime;
          xapiData.duration = templateEvent.duration;
          break;
        case "videoPause":
        case "audioPause":
          xapiData.startingPoint = templateEvent.startTime;
          xapiData.endingPoint = templateEvent.currentTime;
          xapiData.duration = templateEvent.duration;
          break;
        case "videoSeeking":
        case "audioSeeking":
          xapiData.startingPoint = templateEvent.seekFrom;
          xapiData.endingPoint = templateEvent.currentTime;
          xapiData.duration = templateEvent.duration;
          break;
        case "audioSeeked":
        case "videoSeeked":
          xapiData.endingPoint = templateEvent.currentTime;
          xapiData.duration = templateEvent.duration;
          break;
        case "videoComplete":
        case "audioComplete":
          xapiData.startingPoint = templateEvent.duration;
          xapiData.endingPoint = templateEvent.duration;
          xapiData.duration = templateEvent.duration;
          break;
        default:
          break;
      }
      //console.log(templateEvent.type, xapiData);
      return xapiData;
    };
    var _getSmartV2EventProperties = function (templateEvent) {
      return {
        "attempt": {
          "id": templateEvent.attemptId,
          "number": templateEvent.attemptNumber
        },
        "xapiData": _getSmartXAPIDataProperty(templateEvent),
        "data": templateEvent.data
      };
    };
    var _getExtensions = function (templateEvent) {
      var extension = {};
      switch (templateEvent.data.componentName) {
        case 'qListeningActivity':
          extension = {
            "ntxModelJson": {
              "mode": templateEvent.mode,
              "status": templateEvent.status,
              "incorrectAreas": JSON.stringify(app.compController.getModelById(templateEvent.id).get('incorrectAreas')) || "[]"
            }
          };
          break;
        case 'qDrawActivity':
          extension = {
            "ntxModelJson": {
              "mode": templateEvent.mode,
              "status": templateEvent.status,
              "canvasArea": {
                originWidth: $$('#' + templateEvent.id).find('#canvas').attr('width'),
                originHeight: $$('#' + templateEvent.id).find('#canvas').attr('height'),
              }
            }
          };
          break;
        case 'passWordGame':
          extension = {
            "ntxModelJson": {
              "mode": templateEvent.mode,
              "status": templateEvent.status,
              "current": templateEvent.data.data.current,
              "popupType": templateEvent.data.data.popupType,
              "time": templateEvent.data.data.time,
              "timerType": templateEvent.data.data.timerType,
              "finished": templateEvent.data.data.finished
            }
          };
          break;
        default:
          extension = {
            "ntxModelJson": {
              "mode": templateEvent.mode,
              "status": templateEvent.status
            }
          };
          break;
      }
      return extension;

    };
    var _prepareSmartEvent = function (templateEvent) {
      var smartEvent = _getSmartBaseEvent(templateEvent);
      if (_smartEventVersion === 1) _.extend(smartEvent, _getSmartV1EventProperties(templateEvent));
      else _.extend(smartEvent, _getSmartV2EventProperties(templateEvent));
      if (smartEvent.typeEvent === "checked" || smartEvent.typeEvent === "response" || smartEvent.typeEvent === "firstResponse") {
        smartEvent.extensions = _getExtensions(templateEvent);
      }
      if (_isSmartAudioVideoEvent(smartEvent.typeEvent)) {
        smartEvent.mode = null;
      }
      return smartEvent;
    };
    var _translateSmartEventArray = function (smartEventsArray, cb) {
      try {
        var translationObject = XAPIEventTranslator.translateSmartEventArrayToXAPI(smartEventsArray, _xAPIStatementVersion);
        if (translationObject.errors.length === 0) return cb(null, translationObject.statements);
        else {
          return cb({ message: 'There are errors on translation', details: JSON.stringify(translationObject.errors, 2) });
        }
      } catch (error) {
        return cb({ message: 'There are exceptions on translation process', details: error });
      }
    };
    var _sendSmartEventsToXAPIEndpoint = function (smartEventsArray, cb) {
      _translateSmartEventArray(smartEventsArray, function (err, statements) {
        var url = smart.scaResponse.get("statementsUrl");
        if (!err) {
          var sectionId = null;
          sectionId = statements[0].context.extensions['https://w3id.org/xapi/smart/extension/context/interaction-context'].sectionId;
          if (url) {
            smart.http.post("statements", url, statements);
            return cb(null);
          }
        } else {
          var error = {
            data: { message: err },
            status: 500,
            statusText: err
          };
          smart.http.logError(error, url, "POST", "eventTranslation");
          return cb(err);
        }
      });
    };
    return {
      require: ["eventBus", "utils", "http", "localStorage", "scaResponse", "student", "integration"],
      init: function () {
        _init();
      }
    };
  })();
})(window.smart = window.smart || {});

(function (smart) {
  "use strict";
  var enable = {
    "name" : "enableDiscussion",
    "data" : {
      "timestamp" : new Date().getTime()
    }
  };
  var disable = {
    "name" : "disableDiscussion",
    "data" : {
      "timestamp" : new Date().getTime()
    }
  };
  smart.statementsDiscussion = (function () {
    var xapiVersionURLParameter = parseInt(smart.utils.getURLParameter('xAPIStatementVersion'));
    var _xAPIStatementVersion = !isNaN(xapiVersionURLParameter) ? xapiVersionURLParameter : 2;
    var _init = function () {
      smart.eventBus.trigger("moduleLoaded", "statementsDiscussion");
    };
    var _getContext = function (id) {
      var currentLesson = smart.scaResponse.get("currentLesson");
      currentLesson = currentLesson.substring(0, currentLesson.lastIndexOf("/") + 1);
      currentLesson = currentLesson + smart.statementsIntegration.getCurrentPage(id);
      return {
        "bookUri": smart.scaResponse.get("bookUri"),
        "unitUri": smart.scaResponse.get("unitUri"),
        "sectionId": smart.scaResponse.get("sectionId"),
        "userId": smart.scaResponse.get("userId"),
        "role": smart.scaResponse.isTeacherOrCoteacher() ? "teacher" : "student",
        "tenantId": smart.scaResponse.get("tenantId"),
        "lessonUri": currentLesson
      };
    };
    var _getSmartBaseEvent = function (xApiData, type) {
      var activityId = xApiData.activityId;
      var context = _getContext(activityId);
      return {
        "context": context,
        "componentId": activityId,
        "activityId": smart.integration.getActivityUri(activityId),
        "typeActivity": smart.statementsIntegration.getActivityIriById(activityId),
        "typeEvent": type.name,
        "xapiData":type.data
      };
    };

    var _translateSmartEventArray = function (smartEventsArray, cb) {
      try {
        var translationObject = XAPIEventTranslator.translateSmartEventArrayToXAPI(smartEventsArray, _xAPIStatementVersion);
        if (translationObject.errors.length === 0) {
          return cb(null, translationObject.statements);
        } else {
          return cb({message: 'There are errors on translation', details:JSON.stringify(translationObject.errors,2)});
        }
      } catch (error) {
        return cb({message: 'There are exceptions on translation process', details:error});
      }
    };
    var _sendSmartEventsToXAPIEndpoint = function(smartEventsArray, cb) {
      _translateSmartEventArray(smartEventsArray, function(err, statements) {
        if (!err) {
         // console.log('There are %s statements to send', statements.length);
          var url = smart.scaResponse.get("statementsUrl");
         // console.log('Sending statements to ', url);
          if (url) {
            smart.http.post("discussion",url, statements);
            return cb(null);
          }
        } else {
          console.log('Error in translating event', err);
          return cb(err);
        }
      });
    };
    return {
      require: ["eventBus", "utils", "http", "localStorage", "scaResponse","integration"],
      init: function () {
        _init();
      },
      getActivityUri: function(activityId){
        return smart.integration.getActivityUri(activityId);
      },
      enableDiscussion: function (xApiData){
        var smartEvent = [];
         smartEvent.push(_getSmartBaseEvent(xApiData,enable));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
        });
      },
      disableDiscussion: function (xApiData){
        var smartEvent = [];
         smartEvent.push(_getSmartBaseEvent(xApiData,disable));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
          });
      },
      postDiscussionTopic: function (xApiData, callback){
        var post = {
          "name" : "postDiscussionTopic",
          "data" : {
            "timestamp" : new Date().getTime(),
            "message" : {
              "id": xApiData.topic.id,
              "content": xApiData.topic.content
            },
            "extendedUserData": {
              "smartUserName": xApiData.topic.user.name +' '+ xApiData.topic.user.surname,
              "smartUserAvatar": xApiData.topic.user.avatar
            }
          }
        };
        var smartEvent = [];
        smartEvent.push(_getSmartBaseEvent(xApiData,post));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
          callback();
        });
      },
      deleteMessage: function (xApiData){
        var del = {
          "name" : "deleteDiscussionMessage",
          "data" : {
            "timestamp" : new Date().getTime(),
            "deletedMessage": {
              "id": xApiData.topicId
            }
          }
        };
        var smartEvent = [];
        smartEvent.push(_getSmartBaseEvent(xApiData,del));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
        });
      },
      replyDiscussionTopic : function (xApiData, callback){
        var reply = {
          "name" : "replyToDiscussionMessage",
          "data" : {
            "timestamp" : new Date().getTime(),
            "message" : {
              "id": xApiData.topic.id,
              "content": xApiData.topic.content
            },
            "repliedMessage": {
              "id": xApiData.topic.repliedMessage
            },
            "extendedUserData": {
              "smartUserName": xApiData.topic.user.name +' '+ xApiData.topic.user.surname,
              "smartUserAvatar": xApiData.topic.user.avatar
            }
          }
        };
        var smartEvent = [];
        smartEvent.push(_getSmartBaseEvent(xApiData,reply));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
          callback();
        });
      },
      reportMessage: function (xApiData){
        var report = {
          "name" : "reportDiscussionMessage",
          "data" : {
            "timestamp" : new Date().getTime(),
            "handledMessage": {
              "id": xApiData.topicId
            }
          }
        };
        var smartEvent = [];
        smartEvent.push(_getSmartBaseEvent(xApiData,report));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
        });
      },
      likeMessage: function (xApiData){
        var like = {
          "name" : "likeDiscussionMessage",
          "data" : {
            "timestamp" : new Date().getTime(),
            "handledMessage": {
              "id": xApiData.topicId
            }
          }
        };
        var smartEvent = [];
        smartEvent.push(_getSmartBaseEvent(xApiData,like));
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
          //console.info(response);
        });
        var discussion = smart.activityDiscussion.getDiscussion(xApiData.activityId);
        discussion.messages = discussion.messages.map(function (message) {
          if(message.id === xApiData.topicId) {
            message.likes.push(smart.scaResponse.get('userId'));
          } else {
            message.replies = message.replies.map(function (reply) {
              if(reply.id === xApiData.topicId) {
                reply.likes.push(smart.scaResponse.get('userId'));
              }
              return reply;
            });
          }
          return  message;
        });
        smart.activityDiscussion.saveDiscussion(discussion);
      }
    };
  })();
})(window.smart = window.smart || {});

(function (smart) {
  "use strict";
  smart.statementsIntegration = (function () {
    var _memoLikertCounter = 0;
    var _getAttemptData = function (type, e) {
      var eventId = e.id;
      var data = smart.localStorage.getItem("smart_statement_" + eventId);
      var attemptNumber = smart.statementsIntegration.getAttemptNumber(eventId);
      var id;
      var sequence;
      var lastPlay = 0;
      if (type === "firstResponse" || !data || type === "videoPlay" && smart.utils.getVal(e, "currentTime") === 0 && isNaN(smart.utils.getVal(e, "duration")) || type === "audioPlay" && smart.utils.getVal(e, "currentTime") === 0 && isNaN(smart.utils.getVal(e, "duration"))) {
        id = smart.utils.getUUID();
        sequence = 0;
        if (type === "firstResponse" && attemptNumber < 1) {
          attemptNumber = attemptNumber + 1;
          smart.statementsIntegration.setAttemptNumber(eventId, attemptNumber);
        }
      } else {
        id = _.first(data.split("|"));
        attemptNumber = attemptNumber;
        sequence = (+data.split("|")[1]) + 1;
      }

      if (type === "audioPlay" || type === "videoPlay") {
        lastPlay = smart.utils.getVal(e, "currentTime") ? smart.utils.getVal(e, "currentTime") : 0;
      }

      smart.localStorage.setItem("smart_statement_" + eventId, id + "|" + sequence + "|" + lastPlay);

      return {
        "attemptId": id,
        "attemptNumber": attemptNumber,
        "sequence": sequence,
        "lastPlay": lastPlay
      };
    };
    var _getMode = function (id) {
      return app.compController.getModelById(id).get("mode");
    };
    var _getStatus = function (id) {
      return app.compController.getModelById(id).get("status");
    };
    var _getLikertResponseAndSend = function (e) {
      var likertActivityComp = app.dat.getParentCompById(e.id);
      var likertActivityCompId = likertActivityComp.id;
      _memoLikertCounter++;
      if (_memoLikertCounter === app.dat.getChildIdsByName(likertActivityCompId, "qLikertQuestion").length) {
        var likertModel = app.compController.getModelById(likertActivityCompId);
        _sendStatementEvent("checked", {
          "attempt": likertModel.get("attempt") - 1,
          "description": app.dat.getActivityWording(likertActivityCompId),
          "duration": 0,
          "id": likertActivityCompId,
          "options": app.dat.getChildsByProperty(likertActivityCompId, "quizOption"),
          "response": JSON.parse(likertModel.get('response')),
          "score": 100,
          "solution": {},
          "status": "C"
        });
        _memoLikertCounter = 0;
      }
    };
    var _sendDebounced = _.debounce(function (e) {
      _sendStatementEvent("response", _.clone(e));
    }, 600);
    var _init = function () {
      app.activityConfig.changeAttempt = "tryAgain";
      app.eventBus
        .on("activity:attempt", function (e) {
          smart.statementsIntegration.setAttemptNumber(e.id, e.attempt);
        })
        .on("activity:firstResponse", function (e) {
          if (app.dat.getCompName(e.id) !== "qEssayActivity" && app.dat.getCompName(e.id) !== "qFillInActivity") {
            _sendStatementEvent("firstResponse", _.clone(e));
          } else {
            _filterEmptyResponse(e);
          }
        })
        .on("activity:response", function (e) {
          if (app.dat.getCompName(e.id) === "qDrawActivity") {
            _sendDebounced(e);
          } else if (app.dat.getCompName(e.id) !== "qEssayActivity" && app.dat.getCompName(e.id) !== "qFillInActivity") {
            _sendStatementEvent("response", _.clone(e));
          }
        })
        .on("activity:checked", function (e) {
          if (app.dat.getCompName(e.id) === "qLikertQuestion") {
            _getLikertResponseAndSend(e);
          } else {
            _sendStatementEvent("checked", _.clone(e));
          }
        })
        .on("openAnswer:response", function (e) {
          _sendStatementEvent("response", _.clone(e));
        })
        .on("activity:incorrectResponse", function (e) {
          if (app.compController.getModelById(e.id).previous("mode") === "doingN") {
            _sendStatementEvent("firstResponse", _.clone(e));
            _sendStatementEvent("response", _.clone(e));
          } else {
            _sendStatementEvent("response", _.clone(e));
          }
        })
        .on("video.play", function (e) {
          _sendStatementEvent("videoPlay", _.clone(e));
        })
        .on("video.pause", function (e) {
          _sendStatementEvent("videoPause", _.clone(e));
        })
        .on("video.seeked", function (e) {
          _sendStatementEvent("videoPlay", _.clone(e));
        })
        .on("video.seeking", function (e) {
          _sendStatementEvent("videoPause", _.clone(e));
        })
        .on("video.complete", function (e) {
          _sendStatementEvent("videoComplete", _.clone(e));
        })
        .on("audio.play", function (e) {
          _sendStatementEvent("audioPlay", _.clone(e));
        })
        .on("audio.pause", function (e) {
          _sendStatementEvent("audioPause", _.clone(e));
        })
        .on("audio.seeking", function (e) {
          _sendStatementEvent("audioPause", _.clone(e));
        })
        .on("audio.seeked", function (e) {
          _sendStatementEvent("audioPlay", _.clone(e));
        })
        .on("audio.complete", function (e) {
          _sendStatementEvent("audioComplete", _.clone(e));
        })
        .on("smart:send:file", function (e) {
          _uploadFile(e);
        })
        ;
      smart.eventBus.trigger("moduleLoaded", "statementsIntegration");
    };
    var _flattenObject = function (ob) {
      var toReturn = {};
      for (var i in ob) {
        if (!ob.hasOwnProperty(i)) {
          continue;
        }
        if ((typeof ob[i]) === 'object') {
          var flatObject = _flattenObject(ob[i]);
          for (var x in flatObject) {
            if (!flatObject.hasOwnProperty(x)) {
              continue;
            }
            toReturn[i + '.' + x] = flatObject[x];
          }
        } else {
          toReturn[i] = ob[i];
        }
      }
      return toReturn;
    };
    var _getValuesNaN = function (obj) {
      var flatObject = _flattenObject(obj);
      var arr = [NaN, null];
      var ret = [];
      _.each(arr, function (v) {
        var exist = (_.invert(flatObject))[v];
        if (!!exist) {
          ret.push(exist);
        }
      });
      return ret;
    };
    var _filterEmptyResponse = function (obj) {
      if (obj.response !== "{}") {
        _sendStatementEvent("firstResponse", _.clone(obj));
      }
    };
    var _sendStatementEvent = function (type, e) {
      if ((e.id).indexOf("discussion_") !== -1) {
        e.id = (e.id).replace("discussion_", "");
      }
      var data = _getAttemptData(type, e);
      //fix attempts issue for passWordGame
      if( app.dat.getCompName(e.id) === "passWordGame") {
        data.attemptNumber = smart.statementsIntegration.getAttemptNumber(e.id) +1;
      }
      var originalEvent = _.clone(e);
      e.attemptId = data.attemptId;
      e.attemptNumber = data.attemptNumber;
      e.sequence = data.sequence;
      e.mode = _getMode(e.id);
      e.status = _getStatus(e.id);
      e.type = type;
      e.typeActivity = smart.statementsIntegration.getActivityIriById(e.id);
      switch (type) {
        case "audioPause":
          case "videoPause":
            if (originalEvent.seekFrom) {
              e.currentTime = originalEvent.seekFrom;
            }
            break;
            case "videoPlay":
              if (originalEvent.startTime) {
                _.omit(e, ['startTime', 'endTime']);
                _.omit(originalEvent, ['startTime', 'endTime']);
              }
              break;
              ///***///
            }
      e.data = {
        "timestamp": _.now(),
        "componentName": app.dat.getCompName(e.id),
        "data": originalEvent
      };
      var isValueNaN = _getValuesNaN(e);
      if (_.size(isValueNaN) && isValueNaN !== "duration") {
        e.isValueNaN = isValueNaN;
        var err = {
          data: { message: "SmartContent error type event " + type + " contain parameter NaN: " + isValueNaN },
          status: 400,
          statusText: { data: e }
        };
        smart.http.logError(err, smart.scaResponse.get("statementsUrl"), "POST", "NaN_" + isValueNaN);
      }
      smart.eventBus.trigger("statement", e);
    };
    var _uploadFile = function (data) {
      if (data.file.size <= smart.scaResponse.get('maxUploadSize') * 1024 * 1024) {
        var url = smart.scaResponse.get("assetPresignService");
        var url2 = smart.scaResponse.get("assetService");
        axios.get(url + "?fileName=" + data.fileName + "&assetType=SMART_ASSET").then(function (preSignedRequest) {
          var uploadData = new FormData();
          var isBodyExtended = Object.keys(preSignedRequest.data.body).length > 0;
          if (isBodyExtended) {
            var keysObj = Object.keys(preSignedRequest.data.body);
            var valuesObj = Object.values(preSignedRequest.data.body);
            for (var i = 0; i < keysObj.length; i++) {
              uploadData.append(keysObj[i], valuesObj[i]);
            }
            uploadData.append('file', data.file, data.fileName);
          } else {
            Object.defineProperty(data.file, 'name', {
              writable: true,
              value: data.fileName
            });
          }
          axios({
            url: preSignedRequest.data.url,
            method: preSignedRequest.data.method,
            headers: preSignedRequest.data.headers,
            data: isBodyExtended ? uploadData : data.file,
            preventInterceptors: true
          }).then(function () {
            var payload = {
              uuid: preSignedRequest.data.uuid,
              fileName: data.fileName,
              assetType: "SMART_ASSET",
              mimeType: data.file.type
            };
            return axios.post(url2, payload).then(function (res) {
              app.eventBus.trigger(data.activityId + ':smart:uploaded:file', res);
            });
          });
        }).catch(function () {
          app.eventBus.trigger(data.activityId + ':smart:uploaded:file', {
            status: 400,
            error: 'errorFileName'
          });
        });
      } else {
        app.eventBus.trigger(data.activityId + ':smart:uploaded:file', {
          status: 400,
          error: 'errorSize'
        });
      }
    };
    return {
      require: ["integration", "eventBus", "utils", "localStorage", "http", "student"],
      init: function () {
        _init();
      },
      getActivityUri: function (id) {
        return smart.integration.getActivityUri(id);
      },
      getActivityIriById: function (id) {
        return smart.scaResponse.getIri(app.dat.getCompName(id));
      },
      getCurrentPage: function (id) {
        return app.dat.closest(id, "pageContent") ? app.dat.closest(id, "pageContent") : app.dat.getCurrentPage();
      },
      getAttemptNumber: function (id) {
        return !!app.compController.getModelById(id).attributes.attempt ? app.compController.getModelById(id).attributes.attempt : 0;
      },
      setAttemptNumber: function (id, num) {
        app.kSuspendStorage.setItem(id, num);
        app.eventBus.trigger("tracking:onChangeSuspend");
      }
    };
  })();
})(window.smart = window.smart || {});

(function (smart) {
  "use strict";
  smart.statementsTeacherIntegration = (function () {
    var xapiVersionURLParameter = parseInt(smart.utils.getURLParameter('xAPIStatementVersion'));
    var _xAPIStatementVersion = !isNaN(xapiVersionURLParameter) ? xapiVersionURLParameter : 2;
    var _init = function () {
      smart.eventBus.trigger("moduleLoaded", "statementsTeacherIntegration");
    };
    var _getContext = function (id) {
      var currentLesson = smart.scaResponse.get("currentLesson");
      currentLesson = currentLesson.substring(0, currentLesson.lastIndexOf("/") + 1);
      currentLesson = currentLesson + _getCurrentPage(id);
      return {
        "bookUri": smart.scaResponse.get("bookUri"),
        "unitUri": smart.scaResponse.get("unitUri"),
        "sectionId": smart.scaResponse.get("sectionId"),
        "userId": smart.scaResponse.get("userId"),
        "role": smart.scaResponse.isTeacherOrCoteacher() ? "teacher" : "student",
        "tenantId": smart.scaResponse.get("tenantId"),
        "lessonUri": currentLesson
      };
    };
    var _getSmartBaseEvent = function (xApiData) {
      var activityId = xApiData.activityId;
      var context = _getContext(activityId);
      var attemptId = smart.utils.getUUID();
      return {
        "context": context,
        "componentId": activityId,
        "activityId": smart.integration.getActivityUri(activityId),
        "typeActivity": _getActivityIriById(activityId),
        "typeEvent": "evaluated",
        "attempt":{
          "id": attemptId,
          "number":xApiData.evaluatedAttempt.number
        },
        "xapiData": _getSmartXAPIDataProperty(xApiData)
      };
    };
    var _getSmartXAPIDataProperty = function(xApiData) {
      var xapiData = {
        "timestamp": Date.now(),
        "status": xApiData.score >= 50 ? "P" : "F",
        "score": xApiData.score,
        "evaluatedUserId": xApiData.userId,
        "teacherFeedback": xApiData.feedback,
        "response": xApiData.response,
        "evaluatedAttempt": xApiData.evaluatedAttempt
      };
      return xapiData;
    };
    var _translateSmartEventArray = function (smartEventsArray, cb) {
      try {
        var translationObject = XAPIEventTranslator.translateSmartEventArrayToXAPI(smartEventsArray, _xAPIStatementVersion);
        if (translationObject.errors.length === 0) return cb(null, translationObject.statements);
        else {
          return cb({message: 'There are errors on translation', details:JSON.stringify(translationObject.errors,2)});
        }
      } catch (error) {
        return cb({message: 'There are exceptions on translation process', details:error});
      }
    };
    var _sendSmartEventsToXAPIEndpoint = function(smartEventsArray, cb) {
      // console.log(JSON.stringify(smartEventsArray));
      _translateSmartEventArray(smartEventsArray, function(err, statements) {
        if (!err) {
          //console.log('There are %s statements to send', statements.length);
          var sectionId = null;
          sectionId = statements[0].context.extensions['https://w3id.org/xapi/smart/extension/context/interaction-context'].sectionId;
          var url = smart.scaResponse.get("statementsUrl");
         // console.log('Sending statements from section %s to ', sectionId, url);
          if (url) {
            smart.http.post("statements",url, statements);
            return cb(null);
          }
        } else {
          console.log('Error in translating event');
          console.log(err);
          return cb(err);
        }
      });
    };
    var _getCurrentPage = function(id){
      return app.dat.closest(id, "pageContent") ? app.dat.closest(id, "pageContent") : app.dat.getCurrentPage();
    };
    var _getActivityIriById = function(id){
      return smart.scaResponse.getIri(app.dat.getCompName(id));
    };
    return {
      require: ["eventBus", "utils", "http", "localStorage", "scaResponse", "teacher","integration"],
      init: function () {
        _init();
      },
      getActivityUri: function (id) {
         return smart.integration.getActivityUri(id);
      },
      sendActivityFeedback: function (xApiData){
        var smartEvent = [];
         smartEvent.push(_getSmartBaseEvent(xApiData));
       // console.info(smartEvent);
        _sendSmartEventsToXAPIEndpoint(smartEvent,function(response){
         // console.info(response);
        });
      }
    };
  })();
})(window.smart = window.smart || {});

