(function(smart){
    "use strict";
    smart.studentListener = (function(){
        var  _unicBrowserId = Math.random() * (1000);
        var _duplicateSession = false;
        var _userPersonalEvent;
        var _retries = [1000, 2000];
        var _init = function(){
            _userPersonalEvent =
            smart.scaResponse.get('userId') +
            smart.scaResponse.get('unitUri') +
            smart.scaResponse.get('sectionId');
    
            smart.eventBus
            .on('stomp:onStudentNotification:' + _userPersonalEvent + ":loginUser", _onLogin)
            .on('stomp:onStudentNotification:' + _userPersonalEvent + ":closeDuplicateSession", _onCloseSession)
            .on('electron:' + _userPersonalEvent + ':loginUser', _onLogin)
            .on('electron:' + _userPersonalEvent + ':closeDuplicateSession', _onCloseSession)
            .on("duplicate:setDuplicateSession", _setDuplicateSession);
            
            
            _triggerLoginEvent();


        };
        var _onLogin = function(e){
            if(e.unicBrowserIdSent !== _unicBrowserId){
                smart.stomp.send("student",_userPersonalEvent + ":showDuplicateSession",{
                    "unicBrowserIdSent": _unicBrowserId,
                    "unicBrowserId" : e.unicBrowserIdSent
                });
                if (smart.electronIntegration.isElectron()) {
                    smart.electronIntegration.sendEvent('load-content-duplicate', {
                        "unicBrowserIdSent": _unicBrowserId,
                        "userPersonalEvent": _userPersonalEvent,
                        "unicBrowserId" : e.unicBrowserIdSent
                    });
                }
            }else{
                _checkDuplicateSession(_loadModule, 0);
            }
           
        };
        var _setDuplicateSession = function(e){
            _duplicateSession = e.value;
            _checkDuplicateSession(_loadModule, 0);
        };
        var _onCloseSession = function (e){
            if(e.unicBrowserIdSent === _unicBrowserId){
                $("body").html(
                    '<div class="duplicate-session-view-001">' +
                    '<div class="duplicate-session-view-001-content">' +
                    '<p class="duplicate-session-view-001-content-text">' +
                        smart.translates.get("duplicateSessionClose"), +
                    '</p>' +
                    '</div>' +
                    '</div>');
                window.close();
            }
        };
        var _checkDuplicateSession = function(callback, retry) {
            if (!retry) {
                retry = 0;
            }
            if (retry <= _retries.length - 1 && !_duplicateSession) {
                setTimeout(function () {
                    _checkDuplicateSession(callback, retry + 1);
                }, _retries[retry]);
            } else if (!_duplicateSession){
                callback();
            }
        };
        var _triggerLoginEvent = function(){
            smart.stomp.send("student",_userPersonalEvent + ":loginUser",{
                "unicBrowserIdSent": _unicBrowserId
            });
            if (smart.electronIntegration.isElectron()) {
                smart.electronIntegration.sendEvent('smart-loaded-for-electron', {
                    "unicBrowserIdSent": _unicBrowserId,
                    "userPersonalEvent": _userPersonalEvent
                });

            }
        };
        var _loadModule = function(){
            smart.eventBus.trigger("moduleLoaded","studentListener");
        };
        return {
            require: ["scaResponse","eventBus", "stomp", "state", "electronIntegration"],
            init:function(){
                _init();
            },
            getVar: function (varName) {
                return eval(varName);
            }
        };
    })();
})(window.smart = window.smart || {});

(function (smart) {
    "use strict";
    smart.studentNotAssessableIntegration = (function () {
        var _tpl = "";
        var _enabled = null;

        var _init = function () {
            _tpl = $("#studentNotAssessableTpl").text();
            app.eventBus
                .on("component:inserted", _showData)
                ;
            smart.eventBus
                .trigger("moduleLoaded", "studentNotAssessableIntegration")
                ;
            
            _enabled = smart.scaResponse.get('assessableVisibleStudent');
            if (_enabled) {
                _update();
            }
        };
        var _getActivityComp = function () {
            var notSupported = ["qEssayActivity", "activityNoInteractive", "smartActivityDiscussion", "audio", "video", "onlineVideo", "allTypeVideo", "qDrawActivity", "qLikertActivity", "qFormulaEssayActivity", "qSpeakingActivity", "smartActivityUploadFile"];
            var comps = _.filter(smart.scaResponse.getActivitySupport(), function (act) {
                return !_.contains(notSupported, act);
            });
            return comps;
        };
        var _update = function () {
            _.each(_getActivityComp(), function (v) {
                _updateTemplate(v);
            });
        };
        var _updateTemplate = function (compName) {
            _.each(app.edat.getViews(compName), function (compView) {
                var phtml = smart.utils.getVal(contentWindow, "ntxTemplateJsonViews." + compName + ".views." + compView + ".phtml");
                var length;
                var current = 0;
                phtml = phtml.replace(/(<([^>]+)>)/ig, function (v, p1, p2) {
                    return v.indexOf("<%") === 0 ? "Â¬Â¬Â¬" + p2 + "â‚¬â‚¬â‚¬" : v;
                });
                length = phtml.match(/(<([^>]+)>)/ig).length;
                phtml = phtml.replace(/(<([^>]+)>)/ig, function (v) {
                    current++;
                    return current !== length ? v : _tpl + v;
                });
                phtml = phtml.split("Â¬Â¬Â¬").join("<");
                phtml = phtml.split("â‚¬â‚¬â‚¬").join(">");
                app.templateCache.update(compName, compView, phtml);
            });
        };
        var _showData = _.throttle(function () {
            smart.eventBus.trigger("studentNotAssessableIntegration:showData");
        }, 500);

        return {
            require: ["integration", "eventBus", "scaResponse", "student"],
            init: function () {
                _init();
            }
        };
    })();
})(window.smart = window.smart || {});
