(function (smart) {
    "use strict";
    smart.translates = (function () {
        var _data = {};
        var _init = function () {
            smart.eventBus.trigger("moduleLoaded", "translates");
        };

        var _getLang = function () {
            var origLang = smart.scaResponse.get("contentLang") || navigator.language || navigator.userLanguage;
            return origLang || smart.translatesIntegration.getLang();
        };

        var _loadTranslation = function (lang, callback) {
            if (!lang) {
                callback();
                return;
            }
            var developEnv = _.contains(["localhost", "10.0.0.188", "10.0.0.174", "10.0.0.167", "10.0.0.206", "10.0.0.178"], window.location.hostname);
            var url;
            if (developEnv) {
                url = "src/translations/"+lang+"/generic.json";
            }else {
                url = "translations/"+lang+"/generic.json";
            }
            var xhr = new XMLHttpRequest();
            xhr.onreadystatechange = function () {
                if (xhr.readyState === 4 && xhr.status === 200) {
                    var translations = JSON.parse(xhr.responseText);
                    _data[lang] = translations;
                }
            };
            xhr.open("GET", url, true);
            xhr.send();

            // even if it does not load the translation, the module must load
            callback();
        };

        return {
            require: ["scaResponse", "eventBus", "translatesIntegration"],
            init: function () {
                var lang = _getLang();
                _loadTranslation(lang, _init);
            },
            get: function (key) {
                return smart.utils.getVal(_data, _getLang() + "." + key, key);
            },
            getTranslationObject: function (name) {
                return _data[_getLang()][name];
            },
            getLang: function () {
                return _getLang();
            }
        };
    })();
})(window.smart = window.smart || {});

