                    var type = smart.activityDetailIntegration.getCompName(id);
                    var incomplete = _.has(data, id) ? data[id].incomplete.length : 0;
                    var complete = _.has(data, id) ? data[id].complete.length : 0;
                    var pass = _.has(data, id) ? data[id].pass.length : 0;
                    var fail = _.has(data, id) ? data[id].fail.length : 0;
                    var rest = students - (fail + pass + complete);
                    var unstarted = rest - incomplete;
                    var notAssessable = _.contains(actNotAssessables, id);
                    if (type === "video" || type === "audio" || type === "onlineVideo" || type === "allTypeVideo" || type === "smartActivityDiscussion") {
                        if (_.contains(layers,"DISCUSSION")) {
                            $$("html").find("#activityDetail_" + id + " .activity-detail-add-discussion").addClass("display-discussion");
                            $$("html").find("#activityDetail_" + id + " .activity-detail-show-detail").addClass("display-discussion");
                        }
                        if(type !== "smartActivityDiscussion"){
                            rest = students - pass;
                            unstarted = rest - incomplete - fail;
                        }
                    }
