/**
 * @namespace smart.toastNotification
 * @desc MÃ³dulo muestra las notificaciones de smart.
 * @example
 * smart.eventBus.trigger("smart:toastNotification",{type:"Success",text:"Soy una notificaciÃ³n tipo exito"});
 * smart.eventBus.trigger("smart:toastNotification",{type:"Info",text:"Soy una notificaciÃ³n tipo informacion"});
 * smart.eventBus.trigger("smart:toastNotification",{type:"Error",text:"Soy una notificaciÃ³n tipo error"});
 */
(function(smart) {
	"use strict";
	smart.toastNotification = (function() {
		var duration;
		var tpl = {
			"Success": null,
			"Info": null,
			"Error": null
		};
		var _onToastNotification = function(notification) {
			$("body").find(".toasts-wrap").remove();
			duration = notification.duration || 3000;
			// var fixed = notification.fixed || false;
			var type = _.contains(_.keys(tpl), notification.type) ? notification.type : "Info";
			var text = notification.text || "";
			var toast = $(tpl[type]({
				"text": text
			}));
			$("body").prepend(toast);
			$(toast).find(".toast").animate({
				right: '45px'
			}, 100, function() {
				$(toast).find(".toast").animate({
					right: '32px'
				}, 100, function() {
					_timeout($(toast));
				});
			});
		};
		var _timeout = function(toast) {
			setTimeout(function() {
				toast.find(".toast").animate({
					right: "-310px",
				},100, function() {
					toast.remove();
				});
			}, duration);
		};
		var _init = function() {
			_.each(tpl, function(v, k) {
				tpl[k] = _.template($("#toastNotification" + k + "Tpl").text());
			});
			// $("body").prepend("<div id='smartToastNotificationContainer' class='toastContainer'></div>");
			smart.eventBus.trigger("moduleLoaded","toastNotification");  
			smart.eventBus.on("smart:toastNotification", _onToastNotification);
		};
		return {
			require: ["eventBus"],
			init: function() {
				_init();
			}
		};
	})();
})(window.smart = window.smart || {});
